-- 2905 🏋️ Exercises from the book "luis-enrique-psg-tactical-analysis-and-training-sessions-107-tactics-practices" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'luis-enrique-psg-tactical-analysis-and-training-sessions-107-tactics-practices');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('10v3 rondo in 4-3-3 shape', 'rondo', 'overload', 'in_possession', 26, 26, 'Session 1: Practice 1', 'Luis Enrique (PSG)', 'Keep the ball against a press while holding 4-3-3 positions, with the three central midfielders moving it away from pressure.', '15x10 m box; 10 blue players placed in a 4-3-3 shape around and inside it, 3 white defenders inside.', 'Blues circulate the ball through every position quickly, with DM, LCM and RCM switching it away from the pressure zone the three whites try to create around the ball.', 'Max 2 touches. A defender who wins the ball swaps roles with the blue player who lost it.', NULL, 'Hold the shape; body shape and fast decisions; midfield three keep moving; pass to the far foot to shift play fast.', '10v3', 13, 13, '15 x 10 metres', 15.0, 10.0, NULL, false, false, false, NULL, 10),
  ('3-3-3 passing pattern with rotation', 'passing_unopposed', 'unopposed', 'in_possession', 27, 27, 'Session 1: Practice 2', 'Luis Enrique (PSG)', 'Rehearse a build-up passing route through a 3-3-3 shape, with scanning and support off the ball.', 'Half pitch; red cones mark 3-3-3 positions (back line, midfield three, front three); poles near the full backs; a line of players waiting at RB.', 'RB dribbles up and finds the DM, who combines with RCM and on to LCM; LCM plays RW, RW sets for F, back to RCM and out to LW; LW dribbles through cones and gives to LB moving between poles, LB plays to CB who dribbles back to the start.', 'Players rotate one spot along the route (RB > DM > LCM > RCM > RW > F > LW > LB > CB > RB).', 'Run it in both directions, starting from LB or RB.', 'Open body shape; pass to the correct foot; move and support off the ball; scan before receiving.', '10+ players', 10, NULL, 'half pitch', NULL, NULL, NULL, false, false, false, NULL, 20),
  ('U-shaped build-up pattern past mannequins', 'passing_unopposed', 'unopposed', 'in_possession', 28, 28, 'Session 1: Practice 3', 'Luis Enrique (PSG)', 'Build up in a wide U-shape from the keeper, using correct support angles so play can change direction.', 'Half pitch with goal and GK; 7 outfield players in a 4-3 shape; 6 mannequins standing in for opponents.', 'From the GK the back four and midfield three pass and move through set build-up combinations, with wide CBs, diagonal staggering of DM/LCM/RCM, and the CB and LCM combining in the same channel before switching to the far side.', 'Ball must go through every player using correct support angles.', NULL, 'Maximum width and far-foot passes to switch; movement off the ball for support and high tempo; scan before receiving.', 'GK + 7 outfield', 8, 8, 'half pitch', NULL, NULL, NULL, false, true, true, NULL, 30),
  ('8v6 build-up to three halfway goals', 'positional_game', 'overload', 'in_possession', 29, 29, 'Session 1: Practice 4', 'Luis Enrique (PSG)', 'Build out quickly against a 4-2 block, using the central overload and switches to the weak side to score.', 'Half pitch; GK + 7 blue outfielders in a 4-3 against 6 whites in a 4-2; 3 small goals on the halfway line, big goal with GK behind the blues.', 'Blues start from the GK, keep width and shift the ball to break the white shape, with the DM setting tempo and building overloads, then score in any small goal. Whites defend compactly and counter into the big goal on winning it.', 'Blues score in the 3 small goals; whites score in the big goal.', NULL, 'Quick tempo and constant shifting of the ball; full backs push high and wide; DM controls the play; target the weak side.', '8v6 (GK + 7 v 6)', 14, 14, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 40),
  ('Build-up through right back 4-3-3 v 4-4-2', 'conditioned_game', 'opposed', 'in_possession', 30, 30, 'Session 1: Practice 5', 'Luis Enrique (PSG)', 'Advance the ball on the right by pushing the right back on to make a 3v2, then exploit the half-space to score.', 'Large area with two full-size goals and GKs; blues in 4-3-3, whites in 4-4-2.', 'Blues build from the back past the press; the DM with LCM/RCM picks the moment to advance on the right, RB pushes high, RW comes inside, and the team uses the 3v2 and half-space runs (e.g. LCM) to finish.', 'After every attack or white counter, play restarts from the blue GK for repeated build-ups.', NULL, 'Central midfielders: high tempo passing and correct support angles; well-timed RB forward run and good finishing.', '11v11 (4-3-3 v 4-4-2, +GKs)', 22, 22, NULL, NULL, NULL, NULL, true, true, true, NULL, 50),
  ('4-3-3 midfield support and switch pattern', 'passing_unopposed', 'unopposed', 'in_possession', 38, 38, 'Session 2: Practice 1', 'Luis Enrique (PSG)', 'Train the DM to support the central midfielders and switch play from side to side.', '25x12 m area; 10 players set out in a 4-3-3.', 'Outside players pass in to LCM or RCM, who moves toward the ball; as soon as a central midfielder receives, the DM moves to support, takes the ball and switches it to the other side.', 'As few touches as possible.', NULL, 'High tempo, balanced positions of the midfield three; DM times his movement and supports at an angle; switch play constantly.', '10 players', 10, 10, '25 x 12 metres', 25.0, 12.0, NULL, false, false, false, NULL, 60),
  ('7v3 rondo with DM as central link', 'rondo', 'overload', 'in_possession', 39, 39, 'Session 2: Practice 2', 'Luis Enrique (PSG)', 'Keep possession in build-up shape with the DM offering central support everywhere.', 'Marked box in front of the goal; 2 CBs, 2 full backs, 3 central midfielders and a GK against 3 white defenders.', 'Blues start from a CB and keep the ball in their shape while the DM keeps offering central support and quickly moves the ball on. Whites press as a unit and shoot at the goal at once if they win it.', 'Max 2 touches for blues. Whites counter-attack to score past the GK.', NULL, 'Fast passes and scanning; DM finds central positions and angles to receive; full backs move well to support.', '7v3 (+GK)', 11, 11, NULL, NULL, NULL, NULL, true, true, false, NULL, 70),
  ('7v6 build-up with midfield rotations', 'positional_game', 'overload', 'in_possession', 40, 40, 'Session 2: Practice 3', 'Luis Enrique (PSG)', 'Use midfield rotations triggered by the DM to escape pressure and advance in build-up.', 'Half pitch; GK + blues in 4-3 vs whites in 3-2-1; 3 target goals on the halfway line, big goal with GK behind the blues.', 'Blues keep the ball and move it fast to score in any of the 3 halfway goals. Whites press high and counter into the big goal after winning it.', 'Key condition: the DM triggers a rotation with a lateral run, opening space for a central midfielder (e.g. RCM) to receive and the team to advance.', NULL, 'Visual communication in the midfield three; DM key in switching play; forward runs by centre backs and runs in behind by full backs.', '7v6 (+GK)', 14, 14, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 80),
  ('DM-led attacking combination to finish', 'combination', 'unopposed', 'in_possession', 41, 41, 'Session 2: Practice 4', 'Luis Enrique (PSG)', 'Rehearse quick combinations into the box with the DM receiving between lines and playing forward.', 'Half pitch with goal; 6 players in a 3-3 (3 central midfielders, 2 wingers, 1 forward); 7 red mannequins as defenders plus a GK.', 'Players combine quickly to get into the box and score, CMs supporting the wingers and DM supporting the CMs; at the right moment the DM plays into F and moves between the lines to find LCM or LW running in behind the back line.', NULL, NULL, 'Keep width and vary tempo from the central midfielders; forward moves off the ball and times runs into the box.', '6 + GK (mannequins)', 7, 7, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 90),
  ('6v6 DM as playmaker game', 'small_sided_game', 'opposed', 'in_possession', 42, 42, 'Session 2: Practice 5', 'Luis Enrique (PSG)', 'Attack a 4-2 block using the midfield 3v2 with the DM driving play by forward passes or carries.', 'Half pitch; blues in 3-3 attack a big goal with GK; whites in 4-2 defend it, with 2 small goals on the halfway line to counter into.', 'Blues keep the ball and combine quickly to score, the DM using the 3v2 in midfield to pass forward or carry into space. Whites defend in shape and counter into either small goal on winning it.', NULL, NULL, 'Quick passing and support runs for the forward playing as a false 9; DM thinks vertically; CMs take up the half-spaces and play decisively.', '6v6 (+GK)', 13, 13, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 100),
  ('Right-side triangle wing combination circuit', 'passing_unopposed', 'unopposed', 'in_possession', 51, 51, 'Session 3: Practice 1', 'Luis Enrique (PSG)', 'Quick combination play inside a full back / winger / central midfielder triangle, then circulating the ball to the far side.', 'Attacking half with a 4-3-3 shape minus centre backs (DM, LB, RB, LCM, RCM, LW, RW, F) and a few mannequins as markers.', 'DM plays out to RB; RB, RW and RCM combine around their triangle and RB finds F, who comes off a mannequin and feeds LW. LW, LB and LCM combine on the left, then LW returns it to DM to restart.', NULL, 'Run it in both directions.', 'DM times his movement and supports at an angle; fast passes in the triangle, body open for the next pass, good rhythm.', '8 outfield players + mannequins', 8, 8, NULL, NULL, NULL, NULL, false, false, false, NULL, 110),
  ('Wing triangle then DM switch to weak-side winger', 'passing_unopposed', 'unopposed', 'in_possession', 52, 52, 'Session 3: Practice 2', 'Luis Enrique (PSG)', 'Draw play to one flank with a triangle combination, then switch long to the isolated far winger.', 'Same attacking-half 4-3-3 positions as the previous pattern with mannequins; left winger highlighted in a weak-side zone.', 'DM to RB to RW; RW sets RCM who returns it to RB; RB back to DM, who has slid across, and DM drives a long pass to LW on the weak side. LW plays inside to F, who gives it back to DM to restart.', NULL, 'Run it in both directions.', 'DM shifts to support then switches with a long pass; everyone moves in sync with a steady passing rhythm.', '8 outfield players + mannequins', 8, 8, NULL, NULL, NULL, NULL, false, false, false, NULL, 120),
  ('Wide attack with CM half-space run and cut-back', 'combination', 'unopposed', 'in_possession', 53, 53, 'Session 3: Practice 3', 'Luis Enrique (PSG)', 'Switch play then release a central midfielder''s timed run into the half-space to cut back for the forward.', 'Attacking half with goal and GK, outfield players in 4-3-3 roles, red mannequins as midfield and back line; balls at DM''s start.', 'DM to RB to RW, RW inside to RCM, RCM to F playing as a false 9; F sets DM, who switches to LB. LB to LW, LW slides a pass behind for LCM running into the half-space; LCM drives into the box and cuts back for F to finish.', NULL, 'Run it in both directions.', 'Fast ball speed, winger''s open body shape, timing of the CM''s run, accurate finishing.', '9 outfield + GK + mannequins', 10, 10, NULL, NULL, NULL, NULL, true, true, true, NULL, 130),
  ('Wide attack with full back overlap and cross', 'combination', 'unopposed', 'in_possession', 54, 54, 'Session 3: Practice 4', 'Luis Enrique (PSG)', 'Winger drives inside to open the outside lane for an overlapping full back who crosses for runners.', 'Attacking half with goal and GK, 4-3-3 roles, red mannequins as the defensive line and midfield.', 'Same start as the half-space pattern (DM-RB-RW-RCM-F, F sets DM, switch to LB). LB to LW, who dribbles inside behind the mannequin line and plays to LCM; LCM slips a through ball for LB''s overlap and LB crosses for RW attacking the box.', NULL, 'Run it in both directions.', 'High-tempo synchronised passing and overlap; accurate finishing.', '9 outfield + GK + mannequins', 10, 10, NULL, NULL, NULL, NULL, true, true, true, NULL, 140),
  ('8v8 wide play game with pole gate double goals', 'small_sided_game', 'opposed', 'in_possession', 55, 55, 'Session 3: Practice 5', 'Luis Enrique (PSG)', 'Stretch the pitch wide with the wingers and find ways through the block into the box.', 'Two large goals with GKs; blues in a 2-3-3, whites in a 4-4; two wide pole gates near the blues'' attacking end.', 'Blues move the ball quickly to break the white block and score; whites defend as an organised unit and counter on winning it.', 'A blue goal counts double if the attack went through a wide pole gate first.', NULL, 'Quick passing, switches and third-man runs; flood the box to finish.', '8v8 + 2 GKs', 18, 18, NULL, NULL, NULL, NULL, true, true, true, NULL, 150),
  ('Third-man diamond passing with central midfielders', 'passing_unopposed', 'unopposed', 'in_possession', 64, 64, 'Session 4: Practice 1', 'Luis Enrique (PSG)', 'Central midfielders'' support movements and third-man forward runs to move the ball up to the forward.', '30 x 20 m box with 5 players in a diamond: CB at the base, DM in the middle, LCM and RCM wide, F at the top.', 'CB to LCM moving wide, LCM to DM supporting, DM to RCM who has pushed on as the third man, RCM forward to F dropping in; F returns to CB and it repeats.', NULL, 'Run both ways round the diamond.', 'Movement, support angles and body shape for the next action; high pass speed.', '5', 5, 5, '30 x 20 metres', 30.0, 20.0, NULL, false, false, false, NULL, 160),
  ('8v4 third-man runs quick attack game', 'positional_game', 'overload', 'in_possession', 65, 65, 'Session 4: Practice 2', 'Luis Enrique (PSG)', 'Keep the ball under pressure then break into the attacking half with CMs supporting the forward quickly to finish.', '35 x 20 m split into two halves, two small goals at each end. Lower half 7v3 (blue 4-3-1 minus F vs 3 whites); upper half F vs 1 white (3v1 once CMs arrive).', 'Blues keep the ball in the lower half; after 5 straight passes they play to F in the top half, who drops off his marker to receive, and both CMs sprint up to support and score in either top goal.', 'Max 2 touches in the lower half; whites may not track the runners. If the lower whites win it they try to score in a bottom small goal.', NULL, 'Quick passes and good support angles; forward drops while midfielders sprint into space to finish fast.', '8v4', 12, 12, '35 x 20 metres', 35.0, 20.0, NULL, true, false, true, NULL, 170),
  ('Forward drops so CM makes third-man run', 'combination', 'unopposed', 'in_possession', 66, 66, 'Session 4: Practice 3', 'Luis Enrique (PSG)', 'Forward drops between the lines to open the centre for a central midfielder''s third-man run, finishing via a through ball to the far winger.', '10 outfield players in 4-3-3 roles, GK in goal, 6 mannequins as defenders.', 'Quick passing gets the ball to a winger (LW) who plays to F dropping between the lines; F lays it into space in front of the box for LCM running onto it as the third man; LCM threads a pass between the centre back and full back mannequins for RW sprinting in behind to score.', NULL, NULL, 'Quick passes, body shape for the next action, timing between F and the CM outside the box, accurate finishing.', '10 outfield + GK + mannequins', 11, 11, NULL, NULL, NULL, NULL, true, true, true, NULL, 180),
  ('CM run in behind into half-space from switch', 'combination', 'unopposed', 'in_possession', 67, 67, 'Session 4: Practice 4', 'Luis Enrique (PSG)', 'Central midfielder timing a run between full back and centre back after a long switch, then cutting back.', 'Same set-up as the previous pattern: 4-3-3 roles, GK, mannequins as the opposition back line and midfield.', 'Ball worked out to LW, who passes inside to LCM instead of F; LCM sets DM, DM switches long to RCM who runs in behind between the full back and centre back mannequins; RCM drives on and cuts back for F to score.', NULL, 'Book frames it as a variation of Practice 3 with its own number.', 'High pass speed, DM support angle and body shape, timing of the CM run between mannequins, accurate finishing.', '10 outfield + GK + mannequins', 11, 11, NULL, NULL, NULL, NULL, true, true, true, NULL, 190),
  ('8v6 two-zone third-man runs game', 'phase_of_play', 'overload', 'in_possession', 68, 68, 'Session 4: Practice 5', 'Luis Enrique (PSG)', 'Get the ball into the final zone through a central midfielder''s third-man run behind the defence, with numbers arriving to finish.', 'Half pitch with a big goal at each end; blues 2-3-3 with full backs high, whites 4-2. Poles mark a red line; a final attacking zone in front of the goal.', 'Blues move the ball quickly using F dropping and wide wingers to release a CM into the final zone; once the ball crosses the line at least 3-4 blues join to finish. Whites counter to the big goal on winning it.', 'At least 3 or 4 blue players must enter the final zone once the ball is in.', NULL, 'High speed of play; CMs time third-man runs behind defenders; wingers hold width; quick support into the box.', '8v6 + 2 GKs', 16, 16, NULL, NULL, NULL, NULL, true, true, true, NULL, 200),
  ('10v6 diamond connections possession game', 'possession', 'overload', 'in_possession', 78, 78, 'Session 5: Practice 1', 'Luis Enrique (PSG)', 'Keep the ball while always forming diamond shapes so the man on the ball has several options, even while rotating.', 'Large area with two big goals and GKs; 10 blue outfielders in 4-3-3 vs 6 whites; diamond shapes marked/highlighted in the area.', 'Blues keep possession using both GKs, maintaining the diamond shapes and scanning to keep them when players swap positions. Whites press and counter to score in either goal.', NULL, NULL, 'Talk and visual communication, quick passes, body shape for the next action; whites press together and transition fast.', '10v6 + 2 GKs', 18, 18, NULL, NULL, NULL, NULL, true, true, false, NULL, 210),
  ('Three-player wing rotation finishing pattern', 'combination', 'unopposed', 'in_possession', 79, 79, 'Session 5: Practice 2', 'Luis Enrique (PSG)', 'Rehearse a fast CM-winger-forward rotation on the left that frees the winger inside to shoot.', '4-3-3 positional roles in the attacking half, GK in goal, 8 mannequins as opposition midfield and defence; balls with the CBs.', 'CB to LB who comes inside; LB to F who drops into central midfield as part of the rotation; F back to DM; DM threads a pass to LW, who has cut into the forward''s spot, and LW shoots.', NULL, NULL, 'Few touches, time the rotation just before LB''s pass, correct support angles and receiving positions.', 'outfield 4-3-3 + GK + mannequins', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 220),
  ('Full back overlap with rotation trigger and cut-back', 'combination', 'unopposed', 'in_possession', 80, 80, 'Session 5: Practice 3', 'Luis Enrique (PSG)', 'A DM pass triggers a full back/CM/winger rotation and a long ball for the full back running in behind.', 'Same 4-3-3 roles, GK and mannequins as the previous pattern; balls with the CBs.', 'CB to DM, DM to the other CB - that pass triggers LB, LCM and LW rotating. CB plays a long aerial ball to LB, who has pushed high and run behind the line; LB dribbles on and cuts back to the penalty spot for F to finish, ideally first time.', NULL, 'Book frames it as a variation of Practice 2.', 'Few touches and correct receiving angles; time rotation and runs before the long pass.', 'outfield 4-3-3 + GK + mannequins', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 230),
  ('Vertical pass into zone 14 with winger run', 'combination', 'unopposed', 'in_possession', 81, 81, 'Session 5: Practice 4', 'Luis Enrique (PSG)', 'Forward drops to pull defenders out of zone 14 so the DM can play a vertical pass for the far winger running inside.', '4-3-3 roles, GK, mannequins as midfield and back line, zone 14 marked in front of the box.', 'CB to CB, aerial pass to LW; LW to LCM, back to LB; LB plays forward to F dropping deep, F sets DM. DM fires a vertical pass into zone 14 for RW, who sprinted in behind, and RW drives at goal and shoots.', 'F''s lay-off to DM is RW''s cue to start his run.', 'Book frames it as a variation of Practice 3.', 'Synchronised trigger and run; quality of the DM''s vertical pass.', 'outfield 4-3-3 + GK + mannequins', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 240),
  ('11v9 rotations vs zone defence game', 'phase_of_play', 'overload', 'in_possession', 82, 82, 'Session 5: Practice 5', 'Luis Enrique (PSG)', 'Use coached rotations to create and exploit space against an organised block, then score.', 'Pitch section with a big goal and GK at each end; blues 4-3-3 attacking, whites in a 4-4 defending in a two-zone structure.', 'Play always starts with the blues attacking, using the rotations from the previous practices (e.g. full back overlap and wing rotation) to open space. Whites defend, win the ball and counter into the blue goal.', NULL, NULL, 'Patience to set up the rotations, sudden jump in passing tempo to attack, good communication.', '11v9 + GKs', 20, 22, NULL, NULL, NULL, NULL, true, true, true, NULL, 250),
  ('4(+1)v2 double rondo with forward linking', 'rondo', 'overload', 'in_possession', 91, 91, 'Session 6: Practice 1', 'Luis Enrique (PSG)', 'Forward constantly moving in a central free zone to receive and switch play between two rondos.', '25 x 10 m split by a 2 m central free zone where F (red bib) plays; 4 blues and 2 whites in each half; two small goals at each end.', 'Blues keep the ball 4v2; after 4-5 straight passes they must find F in the free zone, who turns and switches to the blues in the other half, where it continues. Whites win it and score in the two small goals.', 'Max 2 touches for the blues; 4-5 consecutive passes before playing to F.', NULL, 'Quick passes with correct body shape; F always moving to receive between the lines; high tempo from both sides.', '4(+1)v2 in each half: 8 blues + F + 4 whites', 13, 13, '25 x 10 metres', 25.0, 10.0, NULL, true, false, false, NULL, 260),
  ('Build-up with false 9 for 3v2 in attacking zone', 'phase_of_play', 'overload', 'in_possession', 92, 92, 'Session 6: Practice 2', 'Luis Enrique (PSG)', 'Forward drops into midfield to receive then attacks a 3v2 in the final zone.', 'Half pitch with a big goal and GK at the blues'' end and three small goals across halfway; blues 4-3-3, whites 2-4-2. Beyond halfway: 3 blue attackers v 2 white centre backs.', 'Blues build from the back; at the right moment F drops into the main area to receive, then dribbles or passes into the attacking zone where the 3v2 is played to score in the small goals. Whites counter at the big goal on winning it.', NULL, NULL, 'Both CMs go wide to open space for F; good timing of F''s movement; attack fast once the ball is in to use the extra man.', '11 v 8 + GK', 20, 20, NULL, NULL, NULL, NULL, true, true, true, NULL, 270),
  ('Three-zone build-up with false 9 4v3 overload', 'phase_of_play', 'overload', 'in_possession', 93, 93, 'Session 6: Practice 3', 'Luis Enrique (PSG)', 'Progress through three zones, with the forward dropping into midfield to make 4v3, then finishing quickly.', 'Pitch split into low, middle and final zones with a goal and GK at each end; blues 2-3-3, whites 2-3-1; blue wingers start outside on the flanks.', 'Low zone 3v1 with the GK to play into midfield; in the middle zone F drops back to create a 4v3; in the final zone (3v2) F drives forward and LW and RW come in from the flanks to score fast.', NULL, NULL, 'High-speed combinations; forward moves into free lanes; intense winger runs; accurate final pass and finish.', 'blues 8 + GK v whites 6 + GK', 16, 16, NULL, NULL, NULL, NULL, true, true, true, NULL, 280),
  ('False 9 link play and through ball to winger', 'combination', 'unopposed', 'in_possession', 94, 94, 'Session 6: Practice 4', 'Luis Enrique (PSG)', 'DM breaks the line with a pass to the dropping forward, leading to a through ball for the winger''s run.', '4-3-3 roles, GK, 6 mannequins as four defenders and two midfielders.', 'CB-RB-RCM-CB circulation, CBs combine, then out to LB who plays inside to LCM and on to DM. DM splits the line to F who moves between the lines; F sets RCM, who slides a through pass for RW running in behind; RW drives in and cuts back for LW to score.', NULL, NULL, 'Quick combinations with good body shape and support angles; DM and F synchronise timing.', 'outfield 4-3-3 + GK + mannequins', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 290),
  ('False 9 link play then switch to wide winger cross', 'combination', 'unopposed', 'in_possession', 95, 95, 'Session 6: Practice 5', 'Luis Enrique (PSG)', 'Forward links play, then a long switch to the far winger who crosses for diagonal runs into the box.', 'Same set-up as the previous pattern: 4-3-3 roles, GK and mannequins.', 'CB to LB to DM, DM switches to the other CB who plays wide to RB; RB into F between the lines, F sets RCM; RCM switches long to LW on the touchline, who drives forward and crosses for LCM, F or RW to finish first time.', NULL, 'Book frames it as a variation of Practice 4.', 'Wide players keep full width; quick switch by RCM; diagonal runs by F and RW into the box and clean finishing.', 'outfield 4-3-3 + GK + mannequins', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 300),
  ('5v3 counter-press four mini-goal game', 'transition', 'overload', 'to_defend', 102, 102, 'Session 7: Practice 1', 'Luis Enrique (PSG)', 'Keep the ball with quick combinations and win it straight back with the three closest players when it is lost.', '20 x 12 m pitch with two small goals at each end; 5 blues (CB, DM, LCM, RCM, F) against 3 whites, coach with balls on the side.', 'Blues keep possession; whites press and, if they win it, counter to score in any of the four mini goals. On a turnover the three blues nearest the ball swarm the new carrier at once.', 'Blues max 2 touches.', NULL, 'Fast passing and decisions; instant switch to defending; press to block the next pass, not just the ball.', '5v3', 8, 8, '20 x 12 metres', 20.0, 12.0, NULL, true, false, false, NULL, 310),
  ('4v4+2 perimeter keep-ball and counter-press', 'transition', 'overload', 'to_defend', 103, 103, 'Session 7: Practice 2', 'Luis Enrique (PSG)', 'Possession from a perimeter shape using inside jokers, then an immediate counter-press on losing it.', '20 x 12 m pitch with two small goals at each end; 4 blues spread round the edge, 4 whites inside, 2 red jokers inside who help the team in possession.', 'Blues and jokers keep the ball while whites press; if whites win it they try to score in any of the 4 mini goals with the jokers'' help. Blues counter-press at once; teams then swap roles, whites going to the perimeter.', 'Blues max 2 touches; jokers play for the team on the ball.', 'Roles switch so the whites take the perimeter.', 'Hold the possession shape; use the central jokers often; rapid counter-press.', '4v4+2', 10, 10, '20 x 12 metres', 20.0, 12.0, NULL, true, false, false, NULL, 320),
  ('6v5 wide possession with counter-press', 'transition', 'overload', 'to_defend', 104, 104, 'Session 7: Practice 3', 'Luis Enrique (PSG)', 'Positional possession in a wide channel with the three nearest players regaining the ball within 3-4 seconds.', 'Area marked on one flank of the pitch with small goals; 6 blues in their 4-3-3 roles (LB, LW, LCM, DM, F, CB) v 5 whites.', 'Blues keep the ball in their positions; whites press and counter to score in the small goals. When blues lose it the closest three press the carrier straight away.', 'Aim to win the ball back within 3-4 seconds.', 'Can be set up on either flank.', 'Short distances; high pass speed; talk and signal; collective press.', '6v5', 11, 11, NULL, NULL, NULL, NULL, true, false, false, NULL, 330),
  ('6v6 central zone possession and counter-press', 'transition', 'opposed', 'to_defend', 105, 105, 'Session 7: Practice 4', 'Luis Enrique (PSG)', 'Keep the ball in a 2-3-1 shape centrally and counter-press with the closest three on a turnover.', 'Central area in the middle third with mini goals at the end; both teams in a 2-3-1 (blues: 2 CBs, DM, LCM, RCM, F).', 'Blues combine with close support to keep possession; whites press and counter-attack to score. On losing it the nearest three blues press to win it back as fast as possible.', NULL, NULL, 'Keep shape; constant movement for support angles; few touches; communicate in the transition.', '6v6', 12, 12, NULL, NULL, NULL, NULL, true, false, false, NULL, 340),
  ('8v8 counter-pressing conditioned game', 'conditioned_game', 'opposed', 'to_defend', 106, 106, 'Session 7: Practice 5', 'Luis Enrique (PSG)', 'Attack with compact distances so the team is ready to counter-press and win the ball back inside 5 seconds.', 'Half pitch with a full goal and keeper; blues in a 2-3-3, whites in a 1-4-4 plus GKs.', 'Blues attack keeping players and lines close; whites defend hard and counter to score. When blues lose it the nearest three press to regain within 5 seconds, then rebuild their shape.', 'Regain within 5 seconds.', NULL, 'Spacing between players and lines; fast ball; press the carrier at once; block the next pass; re-form shape quickly.', '8v8 (+GKs)', 18, 18, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 350),
  ('Rest defence diamond recovery pattern', 'defending', 'unopposed', 'to_defend', 113, 113, 'Session 8: Practice 1', 'Luis Enrique (PSG)', 'Teach the back three plus DM to snap into a compact 3-1 diamond rest-defence shape.', 'Around the halfway line: LB, CB, CB and DM with balls, coach positioned up near the opposition box.', 'The four pass among themselves; after a set number of passes one plays long to the coach and all four sprint into a tight diamond covering the centre.', NULL, NULL, 'Communicate to keep distances; get into the diamond at speed; hold the 3-1 shape and do not drift wide.', '4 players + coach', 4, 4, NULL, NULL, NULL, NULL, false, false, false, NULL, 360),
  ('4v2 rest defence double press', 'defending', 'opposed', 'to_defend', 114, 114, 'Session 8: Practice 2', 'Luis Enrique (PSG)', 'DM and a defender double up on the receiver while the other two hold cover in the rest-defence diamond.', 'Same four blues (LB, 2 CBs, DM) against 2 white attackers; coach near the opposition box.', 'Middle CB plays long to the coach, who feeds one white attacker; the four blues converge into a pressing diamond, a defender and the DM press the ball while the other two cover space behind.', NULL, 'Follows on from practice 1.', 'Sprint to the new carrier; DM helps double-mark; keep short distances and shape.', '4v2', 6, 6, NULL, NULL, NULL, NULL, false, false, false, NULL, 370),
  ('Rest defence clearing to wide targets', 'defending', 'opposed', 'to_defend', 115, 115, 'Session 8: Practice 3', 'Luis Enrique (PSG)', 'Closest defender contests a long ball and clears it out to a safe wide zone, away from the centre.', 'Two wide target areas marked by the halfway line; 4 blue rest defenders, 2 white attackers moving passively forward, 2 white CBs starting with balls deep.', 'The white CBs combine and one plays long towards an attacker; the nearest blue sprints to contest and clear into a wide target area, the DM also sprints to intercept if possible, and the two CBs shift across to mark the other attacker.', 'Clearances count only into the wide target areas.', 'Follows on from practice 2.', 'Time the run to clear; keep tight cover positions; communicate responsibilities.', '4v4', 8, 8, NULL, NULL, NULL, NULL, false, false, true, NULL, 380),
  ('Rest defence two-zone conditioned game', 'conditioned_game', 'opposed', 'to_defend', 116, 116, 'Session 8: Practice 4', 'Luis Enrique (PSG)', 'Attack with a fixed rest defence and transition quickly to stop the counter through an unmarked winger.', '10v10 (+GK), both 4-3-3; pitch split into attacking zone and a rest defence zone where 3 blue defenders and 3 white attackers are locked, 3 small goals at the halfway end.', 'Blues attack the big goal; when whites win it they play straight to their free winger in the rest defence zone and try to score in one of 3 small goals. Blues transition fast with DM, central midfielders and strong-side winger supporting.', 'Players in the rest defence zone cannot enter the attacking zone.', NULL, 'Lightning transition; delay the winger and stop him turning or driving; create a numbers edge at the back and recover shape.', '10v10 (+GK)', 21, 21, NULL, NULL, NULL, NULL, true, true, true, NULL, 390),
  ('Coach-triggered switch transition game', 'conditioned_game', 'opposed', 'to_defend', 117, 117, 'Session 8: Practice 5', 'Luis Enrique (PSG)', 'Keep compact in possession so a sudden turnover is met by the three nearest players counter-pressing.', '10v10 (+GKs), both teams 4-3-3 on a full/large pitch; coach on the side with balls.', 'Blues keep possession while whites defend passively. At any moment the coach shouts Ball and feeds a white attacker; whites go full intensity to score while blues press the new carrier with the nearest three and recover.', 'Whites passive until the coach''s call.', NULL, 'Close spacing from the start; synchronised transition and recovery runs.', '10v10 (+GKs)', 22, 22, NULL, NULL, NULL, NULL, true, true, true, NULL, 400),
  ('Pressing shifts to coloured mannequins', 'defending', 'unopposed', 'out_of_possession', 125, 125, 'Session 9: Practice 1', 'Luis Enrique (PSG)', 'Whole team shifts together into its pressing shape led by the front three, leaving the weak side empty.', '10 outfield players in a 4-3-3; four different-coloured mannequins stand in as the opposing back four.', 'Coach calls a colour; all 10 shift at once into their pressing shape towards that mannequin as if it had the ball. Wide presses leave the far side empty; central presses squeeze the middle.', NULL, NULL, 'Build a strong side; close distances between players and lines; talk and signal.', '10 players', 10, 10, NULL, NULL, NULL, NULL, false, false, false, NULL, 410),
  ('5v7 high press and transition game', 'small_sided_game', 'opposed', 'out_of_possession', 126, 126, 'Session 9: Practice 2', 'Luis Enrique (PSG)', 'Press as a unit to overload one side, win the ball and finish quickly on the big goal.', 'Marked area in the attacking half; 5 blues in a 2-3 against 7 whites in a 4-2-1 with GK in the large goal; 2 small goals at the other end.', 'Whites try to string 8 passes and then score in a small goal; blues shift together to create a strong-side overload, win it and attack the big goal.', 'Whites need 8 consecutive passes before they can score.', NULL, 'Synchronised pressing; block lanes; fast transition with first-time finishing.', '5v7 (+GK)', 13, 13, NULL, NULL, NULL, NULL, true, true, true, NULL, 420),
  ('6v7 directional high-press game', 'small_sided_game', 'opposed', 'out_of_possession', 127, 127, 'Session 9: Practice 3', 'Luis Enrique (PSG)', 'Forwards arc their press to force play one way, then trap a midfielder with a 4v3 overload.', 'Attacking half; blues in a 3-3, whites in a 4-2-1 with GK in the large goal and 3 small goals at the far end.', 'Whites build out from the back to score in a small goal; blues press in a coordinated way, funnelling to one side and pouncing when a pass goes into a white midfielder, then counter to score in the large goal.', NULL, NULL, 'Steer the press to one side; tight distances; midfielders time it to intercept.', '6v7 (+GK)', 14, 14, NULL, NULL, NULL, NULL, true, true, true, NULL, 430),
  ('Man-to-man press on coach''s STOP', 'defending', 'passive', 'out_of_possession', 128, 128, 'Session 9: Practice 4', 'Luis Enrique (PSG)', 'Compact man-oriented marking with synchronised shifts and a triggered press from the forwards back through midfield.', 'Blues in a 4-3-3 (RB pushed high) against whites in a 4-2-1 with a GK.', 'Whites circulate the ball while blues shift and mark man-to-man. On the coach''s STOP the whites freeze and the nearest three blues sprint to the carrier while the rest squeeze and mark tight; forwards recover into midfield when bypassed.', 'Whites freeze on STOP.', NULL, 'Synchronised shifts; man marking in the centre; press triggered from the front back through the midfield.', '10 v 8 (4-3-3 v 4-2-1 +GK)', 18, 18, NULL, NULL, NULL, NULL, false, true, false, NULL, 440),
  ('Ultra high press strong-side overload game', 'conditioned_game', 'opposed', 'out_of_possession', 129, 129, 'Session 9: Practice 5', 'Luis Enrique (PSG)', 'After a long ball to their keeper, press with a 5v4 strong-side overload, trap play by the touchline and break fast.', 'Blues in a 4-3-3 v whites in a 4-2-3-1 with GK; three small goals on the halfway line behind the blues.', 'Blues combine then play long to the white keeper, who feeds a CB; blues overload the ball side, mark the white midfielders man-to-man, win it or force an error and attack the big goal. If whites break the press they counter to the small goals.', NULL, NULL, 'Strong-side overload; pressure on the ball; fast attack on winning it.', '10v10 (+GK)', 21, 21, NULL, NULL, NULL, NULL, true, true, true, NULL, 450),
  ('Block shifts against a passing back four', 'defending', 'passive', 'out_of_possession', 136, 136, 'Session 10: Practice 1', 'Luis Enrique (PSG)', 'Move as one connected block, shifting to the ball with weak-side players tucking in.', 'Middle third; blues in a 4-3-3 facing 4 whites spread across as a back four.', 'Whites pass across the line at a steady tempo; blues keep adjusting their shape to each new ball position, staying close and shifting together with the far side narrowing.', NULL, NULL, 'Move as a unit; short distances; cover and support.', '10v4', 14, 14, 'middle third', NULL, NULL, NULL, false, false, false, NULL, 460),
  ('Midfield three blocks central passing lanes', 'defending', 'opposed', 'out_of_possession', 137, 137, 'Session 10: Practice 2', 'Luis Enrique (PSG)', 'Three midfielders shift together to shut every passing lane through the centre.', 'Three zones; 3 whites in each end zone, 3 blue midfielders (DM, LCM, RCM) in the middle zone.', 'Whites try to pass through the middle zone to the far end group; the blue three move as a unit to intercept, leaving no gaps.', 'Passes must go through the middle zone to count.', NULL, 'Speed of movement; short distances; quick coordinated direction changes.', '3v6 (10 v 10 +3 shown)', 9, 9, NULL, NULL, NULL, NULL, false, false, true, NULL, 470),
  ('4-4-2 mid-block conditioned game', 'conditioned_game', 'opposed', 'out_of_possession', 138, 138, 'Session 10: Practice 3', 'Luis Enrique (PSG)', 'Defend in a compact 4-4-2 mid-block that blocks the centre and forces play wide, then counter.', 'Middle third with 3 small goals at each end; blues in a 4-4-2 v whites in a 3-4-2-1.', 'Whites combine quickly to break through and score; blues defend in a coordinated way, the central pair blocking forward passes, then transition to score on winning it.', NULL, NULL, 'Minimise distances; strong side for pressing; keep shape with a midfielder screening.', '10v10', 20, 20, 'middle third', NULL, NULL, NULL, true, false, true, NULL, 480),
  ('5v5 DM shields centre backs low block', 'small_sided_game', 'opposed', 'out_of_possession', 139, 139, 'Session 10: Practice 4', 'Luis Enrique (PSG)', 'Defend low with the DM screening the centre backs and forcing play wide, then break to a mini goal.', 'Half pitch; blues in a 4-1 with GK in front of the big goal, whites in a 2-3; 2 small goals at the halfway line.', 'Whites try to break through and score; blues defend in a low block, the DM blocking passes into the white forward and the CBs shuffling across. If blues win it they counter to a small goal.', NULL, NULL, 'Patience in positioning; quick transition to attack.', '5 (+GK) v 5', 11, 11, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 490),
  ('4-1-4-1 low block protecting zone 14', 'conditioned_game', 'opposed', 'out_of_possession', 140, 140, 'Session 10: Practice 5', 'Luis Enrique (PSG)', 'Low block with DM and centre backs forming a triangle to close zone 14 and passes into the box.', 'Half pitch plus; blues in a 4-1-4-1 with GK, whites in a 4-2-3-1 attacking the big goal; a goal at the far end for blue counters.', 'Whites use fast combinations to get into the box and score; blues defend tight and stop entries, with DM and CBs guarding zone 14, then counter quickly when they win it.', NULL, NULL, 'Defend tight so pressure is possible everywhere; supported fast attack after regaining.', '10 (+GK) v 10 (+GK)', 22, 22, NULL, NULL, NULL, NULL, true, true, true, NULL, 500)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
JOIN exercise_categories c ON c.code = v.cat
CROSS JOIN (SELECT id, source_id FROM coaching_books WHERE slug = 'luis-enrique-psg-tactical-analysis-and-training-sessions-107-tactics-practices') b;
